          let tasks = [];
          let appliedDueRange = { from: '', through: '' };
          const validDate = value => {
            const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
            if (!match) return false;
            const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
            if (year < 1 || month < 1 || month > 12 || day < 1) return false;
            const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
            return day <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
          };
          const refreshTasks = async () => {
            tasks = await request(`/api/projects/${encodeURIComponent(project.id)}/tasks`);
            const shown = tasks.filter(task =>
              (filter.value === 'All' || (filter.value === 'Completed') === task.completed) &&
              (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
              (!appliedDueRange.from && !appliedDueRange.through || task.dueDate &&
