            tasksList.querySelectorAll('.task-rename').forEach(form => form.addEventListener('submit', async event => {
              event.preventDefault();
              const input = form.querySelector('input');
              const title = input.value.trim();
              if (!title) { app.querySelector('#message').textContent = 'Task title is required'; return; }
              try {
                await request(`/api/projects/${encodeURIComponent(project.id)}/tasks/${encodeURIComponent(form.dataset.taskId)}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
                app.querySelector('#message').textContent = '';
                await refreshTasks();
              } catch (error) { app.querySelector('#message').textContent = error.message; }
            }));
            tasksList.querySelectorAll('button[data-action="save-date"]').forEach(button => button.addEventListener('click', async () => {
              const input = button.parentElement.querySelector('input[aria-label="Task due date"]');
              const value = input.value.trim();
              try {
                const result = await request(`/api/projects/${encodeURIComponent(project.id)}/tasks/${encodeURIComponent(button.dataset.taskId)}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ dueDate: value || null }) });
                input.value = result.dueDate || '';
                app.querySelector('#message').textContent = '';
                await refreshTasks();
              } catch (error) { app.querySelector('#message').textContent = error.message; }
            }));
            tasksList.querySelectorAll('select[aria-label="Task priority"]').forEach(select => select.addEventListener('change', async () => {
              try {
                await request(`/api/projects/${encodeURIComponent(project.id)}/tasks/${encodeURIComponent(select.dataset.taskId)}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority: select.value }) });
